-- CHALLENGE B: make ingestion safe and auditable
-- Existing schema objects are supplied by network_security_schema.sql.
-- Do NOT recreate tables or the log_alert_status_change trigger.

PRAGMA foreign_keys = ON;

-- 1) The 12-column INSERT used by Python executemany().
-- event_id is generated by INTEGER PRIMARY KEY; event_key is the idempotency key.
-- Python calculates event_key as SHA-256 of the 11 original CSV fields joined by '|'
-- and maps sensor_name to the existing sensors.sensor_id.
INSERT INTO network_events (
    event_key, timestamp, sensor_id, src_ip, dst_ip, src_port, dst_port,
    protocol, event_type, action, bytes, duration_ms
) VALUES (
    :event_key, :timestamp, :sensor_id, :src_ip, :dst_ip, :src_port, :dst_port,
    :protocol, :event_type, :action, :bytes, :duration_ms
)
ON CONFLICT(event_key) DO NOTHING;

-- 2) Idempotency check. Run the Python importer twice; both counts should match.
SELECT COUNT(*) AS network_event_rows FROM network_events;

-- 3) Audit trigger demonstration. Run as one transaction, inspect the history,
-- then ROLLBACK so neither the status update nor audit row persists.
BEGIN;
UPDATE alerts
SET status = 'INVESTIGATING'
WHERE alert_id = 1;
SELECT history_id, alert_id, old_status, new_status, changed_at
FROM alert_status_history
WHERE alert_id = 1
ORDER BY history_id DESC
LIMIT 1;
ROLLBACK;

-- 4) Query used for EXPLAIN QUERY PLAN comparison on a COPY of the database.
-- Before: drop idx_events_src_time on the copy, then run EXPLAIN QUERY PLAN.
-- After: create the composite index on the copy, then run it again.
EXPLAIN QUERY PLAN
SELECT COUNT(*)
FROM network_events
WHERE src_ip = '198.51.100.66'
  AND timestamp >= '2026-09-18T10:00:00'
  AND timestamp <  '2026-09-18T11:00:00';

-- Index already exists in the starter database. This statement is for the copy
-- after collecting the BEFORE plan (it is safe to run more than once).
CREATE INDEX IF NOT EXISTS idx_events_src_time
ON network_events(src_ip, timestamp);

-- 5) Schema/key checks useful when documenting the supplied database.
PRAGMA table_info(network_events);
PRAGMA index_list(network_events);
PRAGMA foreign_key_list(network_events);
SELECT type, name, sql
FROM sqlite_master
WHERE type IN ('table', 'index', 'trigger', 'view')
ORDER BY type, name;
